import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"请求中间件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/request-middleware.md","filePath":"zh-Hans/deep-dive/request-middleware.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/request-middleware.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="请求中间件" tabindex="-1">请求中间件 <a class="header-anchor" href="#请求中间件" aria-label="Permalink to “请求中间件”">​</a></h1><p>请求中间件是围绕 <a href="./request"><code>Request</code> 和 <code>VaultRequest</code></a> 的包装器。下面是插件核心中已有中间件的列表。</p><h2 id="重试中间件" tabindex="-1">重试中间件 <a class="header-anchor" href="#重试中间件" aria-label="Permalink to “重试中间件”">​</a></h2><ul><li>目标：<code>Request</code></li><li>优先级：<code>2000</code></li><li>行为：自动重试请求。接收一个选项对象，包括 <code>maxRetry</code>（数字）和 <code>isRetryable: () =&gt; boolean</code>。可重试的响应带有 <code>Retry-After</code> 头时，等待时间遵循它而不是默认延迟；超过 180 秒的 <code>Retry-After</code> 会原样返回响应而不等待。</li></ul><h2 id="速率限制包装器" tabindex="-1">速率限制包装器 <a class="header-anchor" href="#速率限制包装器" aria-label="Permalink to “速率限制包装器”">​</a></h2><ul><li>目标：<code>Request</code></li><li>优先级：<code>1000</code></li><li>行为：限制远端请求的最大并发数和请求间隔。第二个参数以选项形式接收 <code>maxConcurrency</code> 和 <code>minInterval</code>。限制器是自适应的：429 响应会增大一个节流惩罚，让请求开始时间的间隔拉大（起点 10 ms，上限 2000 ms），其他每个响应都会缩小它。</li></ul><h2 id="取消中间件" tabindex="-1">取消中间件 <a class="header-anchor" href="#取消中间件" aria-label="Permalink to “取消中间件”">​</a></h2><ul><li>目标：<code>Request</code> 和 <code>VaultRequest</code></li><li>优先级：<code>VaultRequest</code> 为 <code>1000</code>，<code>Request</code> 为 <code>4000</code></li><li>行为：请求转发前和进行中检查取消状态，取消时以抛出异常包装请求。与<a href="./file-system-wrappers#cancellation-wrapper">取消包装器</a>配合工作。携带 <code>ignoreCancellation: true</code> 的请求原样通过，后端在取消之后仍能发送清理调用。</li></ul><h2 id="自定义请求头中间件" tabindex="-1">自定义请求头中间件 <a class="header-anchor" href="#自定义请求头中间件" aria-label="Permalink to “自定义请求头中间件”">​</a></h2><ul><li>目标：<code>Request</code></li><li>优先级：<code>3000</code></li><li>向 headers 参数注入额外的请求头。</li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};